def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_D = sum(1 for x in opp if x == 'D')
    my_D = sum(1 for x in my if x == 'D')
    opp_rate = opp_D / n

    last_my = my[-1]
    last_opp = opp[-1]

    if opp_rate > 0.6:
        return 'D'

    if n >= 5:
        last5 = history[-5:]
        my_D_5 = sum(1 for a, b in last5 if a == 'D')
        opp_D_5 = sum(1 for a, b in last5 if b == 'D')
        if my_D_5 >= 2 and opp_D_5 == 0:
            return 'D'

    if n >= 2:
        if history[-2] == ('D', 'C') and history[-1] == ('C', 'C'):
            return 'D'

    if n >= 2:
        if (history[-2][0] == 'D' and history[-2][1] == 'C') or (history[-1][0] == 'D' and history[-1][1] == 'C'):
            return 'C'

    if opp_rate < 0.1 and n >= 10:
        last10 = history[-10:]
        if all(a == 'C' and b == 'C' for a, b in last10):
            return 'D'

    if last_opp == 'D':
        if last_my == 'D' and opp_rate < 0.2:
            return 'C'
        return 'D'
    else:
        return 'C'
